"use client";

import { create } from "zustand";
import type { ChapterId } from "@/lib/narrative";

export type QualityTier = "safe" | "balanced" | "high" | "ultra";

type ExperienceState = {
  chapter: ChapterId;
  progress: number;
  velocity: number;
  quality: QualityTier;
  inspecting: string | null;
  audioEnabled: boolean;
  setChapter: (chapter: ChapterId) => void;
  setMotion: (progress: number, velocity: number) => void;
  setQuality: (quality: QualityTier) => void;
  inspect: (id: string | null) => void;
  setAudio: (enabled: boolean) => void;
};

export const useExperience = create<ExperienceState>((set) => ({
  chapter: "signal",
  progress: 0,
  velocity: 0,
  quality: "balanced",
  inspecting: null,
  audioEnabled: false,
  setChapter: (chapter) => set({ chapter }),
  setMotion: (progress, velocity) => set({ progress, velocity }),
  setQuality: (quality) => set({ quality }),
  inspect: (inspecting) => set({ inspecting }),
  setAudio: (audioEnabled) => set({ audioEnabled }),
}));

