"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect } from "react";
import { useExperience } from "@/store/experience";

type Detail = {
  kicker: string;
  body: string;
  tags?: string[];
  href?: string;
  linkLabel?: string;
};

const PROJECTS: Record<string, string> = {
  "Mak'ma AI OS": "makma-ai-os",
  "Agentic RAG Engine": "agentic-rag-engine",
  "Knowledge Twin": "knowledge-twin",
  "Multimodal AI Studio": "multimodal-ai-studio",
  "Clinical Document Intelligence": "clinical-document-intelligence",
  "Secure Data Copilot": "secure-data-copilot",
  "LLM Eval & Observability": "llm-eval-observability",
  "MLOps Control Plane": "mlops-control-plane",
  "MLOps Production Pipeline": "mlops-production-pipeline",
};

const DETAILS: Record<string, Detail> = {
  "Archive threshold — the point where foundation becomes specialization": {
    kicker: "THRESHOLD / 2023",
    body:
      "The entrance is not decorative. It marks the shift from general information-technology foundations into AI specialization. Everything before it is about compute, data and software; everything after it compounds those foundations into intelligent systems.",
    tags: ["Foundation", "Transition", "AI"],
  },
  "Ganpat University — Information Technology foundation": {
    kicker: "FOUNDATION / 2020—2023",
    body:
      "This artifact represents the period where programming, software, data structures and general computing became the base layer. The archive deliberately begins with ordinary computing rather than pretending the story started with generative AI.",
    tags: ["Information Technology", "Software", "Data"],
  },
  "Computing foundation — before AI": {
    kicker: "COMPUTE",
    body:
      "A reminder that every later AI system still depends on ordinary engineering: execution, storage, interfaces, debugging and reliable software. The old computer exists here as ancestry, not nostalgia.",
    tags: ["Programming", "Systems", "Engineering"],
  },
  "The signal — infrastructure underneath intelligence": {
    kicker: "SIGNAL",
    body:
      "The signal is the archive's continuous motif. Early on it means electricity and connectivity; later it becomes data, knowledge, evidence and agent activity. It is the one visual language that survives the entire timeline.",
    tags: ["Connectivity", "Data Flow", "Continuity"],
  },
  "aivancity — AI & Data Science for Business": {
    kicker: "LEARN / AIVANCITY",
    body:
      "The academic chapter connects mathematics, machine learning, deep-learning foundations, responsible AI, cloud systems and business context. The point is not a list of courses; it is how those disciplines constrain and improve one another.",
    tags: ["AI", "Mathematics", "Responsible AI", "Cloud"],
    href: "https://aivancity.ai/en/program/programme-grande-ecole/home",
    linkLabel: "PROGRAM",
  },
  "Professional practice — data becomes decisions": {
    kicker: "BUILD / 2023—2025",
    body:
      "Professional experience changes the role of data. It stops being an exercise and begins supporting analysis, language systems, governance and decisions. This is where the LEARN and BUILD timelines start crossing repeatedly.",
    tags: ["Analytics", "NLP", "Governance", "Decision Support"],
  },
  "CERC — evidence, document intelligence and traceability": {
    kicker: "EVIDENCE / 2026",
    body:
      "Clinical documents pushed the system toward evidence and provenance: extracting structure, mapping information and keeping a traceable relationship between a generated result and the document it came from.",
    tags: ["Document Intelligence", "Evidence", "Traceability"],
  },
};

function resolveDetail(name: string): Detail {
  const repo = PROJECTS[name];
  if (repo) {
    return {
      kicker: "MAK'MA SYSTEM",
      body:
        "This project is one subsystem in the MAK'MA architecture. In the archive, projects are presented as connected system responsibilities rather than nine unrelated repository cards.",
      tags: ["MAK'MA Labs", "Architecture", "Production AI"],
      href: `https://github.com/maharshimak/${repo}`,
      linkLabel: "OPEN REPOSITORY",
    };
  }

  return (
    DETAILS[name] ?? {
      kicker: "ARCHIVE ARTIFACT",
      body:
        "This artifact belongs to the same timeline and is intended to explain why a capability exists, what changed at that point, and how it connects to later work.",
    }
  );
}

export function ArtifactInspector() {
  const inspecting=useExperience((state)=>state.inspecting);
  const inspect=useExperience((state)=>state.inspect);
  const detail=inspecting ? resolveDetail(inspecting) : null;

  useEffect(()=>{
    if(!inspecting) return;
    const onKey=(event:KeyboardEvent)=>{
      if(event.key==="Escape") inspect(null);
    };
    window.addEventListener("keydown",onKey);
    return()=>window.removeEventListener("keydown",onKey);
  },[inspecting,inspect]);

  return (
    <AnimatePresence>
      {inspecting && detail ? (
        <motion.div
          className="artifact-inspector"
          role="dialog"
          aria-modal="true"
          aria-label={`Inspect ${inspecting}`}
          initial={{opacity:0}}
          animate={{opacity:1}}
          exit={{opacity:0}}
          onClick={()=>inspect(null)}
        >
          <motion.div
            className="artifact-inspector-panel"
            initial={{scale:.97,y:18,filter:"blur(8px)"}}
            animate={{scale:1,y:0,filter:"blur(0px)"}}
            exit={{scale:.985,y:10,filter:"blur(4px)"}}
            transition={{type:"spring",stiffness:260,damping:30}}
            onClick={(event)=>event.stopPropagation()}
          >
            <button className="inspection-back" onClick={()=>inspect(null)}>
              ← RETURN TO ARCHIVE
            </button>
            <p className="ui-kicker">{detail.kicker}</p>
            <h2>{inspecting}</h2>
            <p>{detail.body}</p>

            {detail.tags?.length ? (
              <div className="artifact-tags">
                {detail.tags.map((tag)=><span key={tag}>{tag}</span>)}
              </div>
            ) : null}

            {detail.href ? (
              <a className="artifact-link" href={detail.href} target="_blank" rel="noreferrer">
                {detail.linkLabel ?? "OPEN"} ↗
              </a>
            ) : null}
          </motion.div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

