"use client";

import { motion } from "motion/react";
import { chapters } from "@/lib/narrative";
import { useExperience } from "@/store/experience";

export function ChapterNav() {
  const activeId = useExperience((state) => state.chapter);

  return (
    <nav className="chapter-nav" aria-label="Journey chapters">
      {chapters.map((chapter, index) => {
        const active = chapter.id === activeId;
        return (
          <div className="chapter-nav-item" key={chapter.id}>
            {active ? (
              <motion.span
                className="chapter-nav-active"
                layoutId="chapter-nav-active"
                transition={{ type: "spring", stiffness: 330, damping: 34 }}
              />
            ) : null}
            <span>{String(index + 1).padStart(2, "0")}</span>
            <b>{chapter.title}</b>
          </div>
        );
      })}
    </nav>
  );
}

components/ui/NarrativeOverlay.tsx:
"use client";

import { useEffect } from "react";
import Lenis from "lenis";
import { AnimatePresence, motion } from "motion/react";
import { chapters } from "@/lib/narrative";
import { useExperience } from "@/store/experience";
import { QuickProfile } from "./QuickProfile";
import { ChapterNav } from "./ChapterNav";
import { ArtifactInspector } from "./ArtifactInspector";

export function NarrativeOverlay() {
  const chapterId = useExperience((state) => state.chapter);
  const setMotion = useExperience((state) => state.setMotion);
  const chapter = chapters.find((item) => item.id === chapterId) ?? chapters[0];

  useEffect(() => {
    const lenis = new Lenis({
      duration: 1.05,
      smoothWheel: true,
      syncTouch: false,
      wheelMultiplier: 0.9,
      touchMultiplier: 1,
    });

    lenis.on("scroll", ({ progress, velocity }: { progress: number; velocity: number }) => {
      setMotion(progress, velocity);
    });

    let rafId = 0;
    const raf = (time: number) => {
      lenis.raf(time);
      rafId = requestAnimationFrame(raf);
    };
    rafId = requestAnimationFrame(raf);

    return () => {
      cancelAnimationFrame(rafId);
      lenis.destroy();
    };
  }, [setMotion]);

  return (
    <>
      <header className="hud">
        <a href="#story" className="identity">
          MP <span>MAHARSHI PATEL</span>
        </a>
        <div className="chapter-meter">
          <span>{String(chapters.indexOf(chapter) + 1).padStart(2, "0")}</span>
          <i />
          <span>{chapter.eyebrow}</span>
        </div>
        <nav>
          <a href="https://github.com/maharshimak">GitHub</a>
          <a href="https://www.linkedin.com/in/maharshi-patel-6bb638298/">LinkedIn</a>
        </nav>
      </header>

      <QuickProfile />
      <ChapterNav />
      <ArtifactInspector />

      <section id="story" className="story-space" aria-label="Maharshi Patel interactive career story">
        {chapters.map((item) => (
          <article key={item.id} className="scroll-chapter" aria-label={item.title}>
            <span>{item.year}</span>
          </article>
        ))}
      </section>

      <AnimatePresence mode="wait">
        <motion.aside
          key={chapter.id}
          className="chapter-copy"
          initial={{ opacity: 0, y: 18, filter: "blur(6px)" }}
          animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
          exit={{ opacity: 0, y: -12, filter: "blur(4px)" }}
          transition={{ duration: 0.55, ease: [0.2, 0.8, 0.2, 1] }}
        >
          <p>{chapter.eyebrow}</p>
          <h1>{chapter.title}</h1>
          <h2>{chapter.subtitle}</h2>
          <p className="meaning">{chapter.meaning}</p>
        </motion.aside>
      </AnimatePresence>
    </>
  );
}

